pub fn dump_ColorRecord(
    out: &mut impl Write,
    path: &str,
    value: &ColorRecord,
    base: FontData<'_>,
) -> io::Result<()> {
    let dump_args = crate::dump_support::arguments();
    if !crate::dump_support::enter(path) {
        return writeln!(out, "{path}=traversal-limit");
    }
    {
        let path = &format!("{path}.blue");
        let fieldValue = value.blue();
        writeln!(out, "{path}={}", fieldValue)?;
    }
    {
        let path = &format!("{path}.green");
        let fieldValue = value.green();
        writeln!(out, "{path}={}", fieldValue)?;
    }
    {
        let path = &format!("{path}.red");
        let fieldValue = value.red();
        writeln!(out, "{path}={}", fieldValue)?;
    }
    {
        let path = &format!("{path}.alpha");
        let fieldValue = value.alpha();
        writeln!(out, "{path}={}", fieldValue)?;
    }
    Ok(())
}

pub fn dump_tables(
    out: &mut impl Write,
    path: &str,
    font: &read_fonts::FontRef<'_>,
) -> io::Result<()> {
    use read_fonts::FontRead;
    {
        crate::dump_support::begin_table();
        let path = &format!("{path}.CPAL");
        let tag = Tag::new(b"CPAL");
        match font
            .table_data(tag)
            .ok_or(ReadError::TableIsMissing(tag))
            .and_then(Cpal::read)
        {
            Ok(table) => dump_Cpal(out, path, &table)?,
            Err(error) => writeln!(out, "{path}.error={}", crate::error(error))?,
        }
    }
    Ok(())
}
